  "amber_md_setup_lig/step12_sander_mdrun_warm/amber_md_setup_lig_step12_sander_mdrun_warm_traj.netcdf"
  "amber_md_setup_lig/step12_sander_mdrun_warm/amber_md_setup_lig_step12_sander_mdrun_warm_rst.rst"
  "amber_md_setup_lig/step13_process_mdout_warm/amber_md_setup_lig_step13_process_mdout_warm_dat.dat"
  "amber_md_setup_lig/step14_sander_mdrun_nvt/amber_md_setup_lig_step14_sander_mdrun_nvt_log.log"
  "amber_md_setup_lig/step14_sander_mdrun_nvt/amber_md_setup_lig_step14_sander_mdrun_nvt_traj.netcdf"
